import express from 'express';
import pg from 'pg';

const app = express();
app.use(express.json());

const pool = new pg.Pool({
  host: process.env.DB_HOST,
  port: 5432,
  database: 'inventory',
  user: process.env.DB_USER,
  password: process.env.DB_PASS,
  ssl: process.env.DB_SSL === 'true' ? { rejectUnauthorized: false } : false
});

// Product search endpoint with filtering
app.get('/api/products', async (req, res) => {
  try {
    const { category, sort_by, direction, min_price } = req.query;

    // Base query
    let query = 'SELECT id, name, price, category, stock_count FROM products WHERE 1=1';
    const params = [];

    // Category filter - parameterized
    if (category) {
      params.push(category);
      query += ` AND category = $${params.length}`;
    }

    // Price filter - parameterized
    if (min_price) {
      params.push(parseFloat(min_price));
      query += ` AND price >= $${params.length}`;
    }

    // Sort - dynamic column name (validated against allowlist... or is it?)
    const allowedSorts = ['name', 'price', 'stock_count', 'category'];
    if (sort_by) {
      // Developer thought this was safe because of the allowlist check
      // but the check uses indexOf which matches substrings
      const sortCol = sort_by;
      const dir = direction === 'desc' ? 'DESC' : 'ASC';
      if (allowedSorts.some(col => sortCol.indexOf(col) !== -1)) {
        query += ` ORDER BY ${sortCol} ${dir}`;
      }
    }

    // Limit results
    query += ' LIMIT 100';

    const result = await pool.query(query, params);
    res.json({ products: result.rows });
  } catch (err) {
    console.error('Query error:', err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Health check
app.get('/health', async (req, res) => {
  try {
    await pool.query('SELECT 1');
    res.json({ status: 'healthy' });
  } catch {
    res.status(503).json({ status: 'unhealthy' });
  }
});

// Inventory update - requires auth token
app.put('/api/products/:id/stock', async (req, res) => {
  const authHeader = req.headers['x-internal-token'];
  if (authHeader !== process.env.INTERNAL_TOKEN) {
    return res.status(401).json({ error: 'Unauthorized' });
  }

  const { id } = req.params;
  const { stock_count } = req.body;

  if (!Number.isInteger(stock_count) || stock_count < 0) {
    return res.status(400).json({ error: 'Invalid stock count' });
  }

  try {
    await pool.query(
      'UPDATE products SET stock_count = $1, updated_at = NOW() WHERE id = $2',
      [stock_count, id]
    );
    res.json({ success: true });
  } catch (err) {
    res.status(500).json({ error: 'Update failed' });
  }
});

app.listen(3000, () => console.log('Inventory service on :3000'));
